export const DICTS: Record<Lang, Dict> = { en, ko, ja, tl, es, de };

function detect(): Lang {
  if (typeof window === "undefined") return "en";
  const saved = localStorage.getItem("handover.lang") as Lang | null;
  return saved && saved in DICTS ? saved : "en"; // English by default; the switcher is explicit
}

type Ctx = { lang: Lang; setLang: (l: Lang) => void; t: (k: Key, vars?: Record<string, string | number>) => string };
const I18nContext = createContext<Ctx>({ lang: "en", setLang: () => {}, t: (k) => en[k] });

export function I18nProvider({ children }: { children: React.ReactNode }) {
  const [lang, setLangState] = useState<Lang>("en");
  // eslint-disable-next-line react-hooks/set-state-in-effect -- read saved/browser language after hydration
  useEffect(() => { setLangState(detect()); }, []);
  useEffect(() => { document.documentElement.lang = lang; }, [lang]);
  const value = useMemo<Ctx>(() => ({
    lang,
    setLang: (l) => { localStorage.setItem("handover.lang", l); setLangState(l); },
    t: (k, vars) => {
      let s = DICTS[lang][k] ?? en[k] ?? k;
      if (vars) for (const [key, v] of Object.entries(vars)) s = s.replaceAll(`{${key}}`, String(v));
      return s;
    },
  }), [lang]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export const useT = () => useContext(I18nContext);
